/// <summary>
/// Extension class for the Unit of Measure Conversion Edit or Create form.
/// </summary>
[ExtensionOf(formStr(UnitOfMeasureConversionEditOrCreate))]
final class AVARUMUnitOfMeasureConversionEditOrCreateFrm_Extension
{
    internal boolean _isUnitOrderChanged_AVA = false;

}

Method.Source:
internal boolean isUnitOrderChanged_AVA(boolean isUnitOrderChanged = this._isUnitOrderChanged_AVA)
{
    this._isUnitOrderChanged_AVA = isUnitOrderChanged;
    return this._isUnitOrderChanged_AVA;
}

/// <summary>
/// Updates the caller form's data source to reflect any changes made in this form.
/// </summary>
public void updateCallers()
{
    xArgs args = this.args();

    next updateCallers();

    if (args && args.caller() is FormRun)
    {
        FormRun callerFormRun = args.caller() as FormRun;
        Global::researchAllFormDataSources_AVA(callerFormRun);

        try
        {
            if (this.isUnitOrderChanged_AVA())
            {
                Message::Add(MessageSeverity::Warning, "@AVARUM:UnitOfMeasureConversionChangeOrderPriceDependence");
                this.isUnitOrderChanged_AVA(false);
            }
        }
        catch { }
    }
}
